abstract class Shape {
    private final String name;                        // private: subclasses can't corrupt it.

    protected Shape(String name) {
        if (name == null || name.isBlank()) throw new IllegalArgumentException("name");
        this.name = name;
    }

    public String name() { return name; }

    /** Returns a non-negative area. */
    public abstract double area();
}

class Circle extends Shape {
    private final double radius;

    Circle(double radius) {
        super("circle");                                // Shape part initialised first.
        if (radius < 0) throw new IllegalArgumentException("radius");
        this.radius = radius;
    }

    @Override public double area() { return Math.PI * radius * radius; }
}

public class Shapes {
    static void describe(Shape s) {                     // works for ANY honest Shape.
        System.out.printf("%s %.2f%n", s.name(), s.area());
    }
    public static void main(String[] args) { describe(new Circle(2)); }   // circle 12.57
}
